def import_articles(apps, schema_editor):
    db = schema_editor.connection.alias
    Article = apps.get_model("core", "Article")
    Group = apps.get_model("auth", "Group")
    Permission = apps.get_model("auth", "Permission")
    ContentType = apps.get_model("contenttypes", "ContentType")
    data = Path(__file__).parent.parent / "data" / "blog.json"
    published_at = timezone.now()
    for item in reversed(json.loads(data.read_text(encoding="utf-8"))):
        Article.objects.using(db).create(
            title=item["title"], slug=item["slug"], description=item["description"],
            body=item["body"], status="published", published_at=published_at,
            legacy_cover=f"blog/{item['slug']}.webp", legacy_cover_alt=item["cover_alt"],
            legacy_width=item["width"], legacy_height=item["height"], original_cover=item["original_cover"],
        )
    group = Group.objects.using(db).filter(name="Portfolio editors").first()
    if group:
        content_type, _ = ContentType.objects.using(db).get_or_create(app_label="core", model="article")
        for action in ("view", "add", "change", "delete"):
            permission, _ = Permission.objects.using(db).get_or_create(
                content_type=content_type, codename=f"{action}_article", defaults={"name": f"Can {action} article"},
            )
            group.permissions.add(permission)



